- */
-public class IfElseTest extends GroovyTestCase {
-
-    RuntimeContext context = new RuntimeContext();
-    GroovyCodeVisitor visitor = new Interpreter(context);
-    DummyBean bean = new DummyBean();
-
-    Statement statement1 = new ExpressionStatement( new MethodCallExpression(new VariableExpression("bean"), "foo", new ConstantExpression("abcd")));
-    Statement statement2 = new ExpressionStatement( new MethodCallExpression(new VariableExpression("bean"), "foo", new ConstantExpression("xyz")));
-
-    BooleanExpression trueExpression = new BooleanExpression(ConstantExpression.TRUE);
-    BooleanExpression falseExpression = new BooleanExpression(ConstantExpression.FALSE);
-
-    public void testIfTrue() {
-        assertIfElse("abcd", true, statement1, statement2);
-        assertIfElse("abcd", true, statement1, EmptyStatement.INSTANCE);
-    }
-
-    public void testIfFalse() {
-        assertIfElse("xyz", false, statement1, statement2);
-        assertIfElse("", false, statement1, EmptyStatement.INSTANCE);
-    }
-
-    protected void assertIfElse(Object expected, boolean condition, Statement ifStatement, Statement elseStatement) {
-        BooleanExpression expression = (condition) ? trueExpression : falseExpression;
-        
-        IfStatement block = new IfStatement(expression, ifStatement, elseStatement);
-        block.visit(visitor);
-        
-        assertEquals("bean buffer", expected, bean.getBuffer());
-        
-    }
-    
-    protected void setUp() throws Exception {
-        context.setVariable("bean", bean);
-    }
-}

