-public class RuntimeContextTest extends GroovyTestCase {
-    
-    public void testNormalContext() {
-        RuntimeContext context = new RuntimeContext();
-
-        assertContextVariable(context, "x", null);
-        
-        context.setVariable("x", "abcdef");
-        
-        assertContextVariable(context, "x", "abcdef");
-        assertContextVariable(context, "y", null);
-    }
-
-    public void testNestedContexts() {
-        
-        RuntimeContext parent = new RuntimeContext();
-
-        RuntimeContext context = new RuntimeContext(parent);
-
-        assertContextVariable(context, "x", null);
-        
-        parent.setVariable("x", "abcdef");
-        
-        assertContextVariable(context, "x", "abcdef");
-        
-        context.setVariable("x", "xyz");
-        
-        assertContextVariable(context, "x", "xyz");
-        assertContextVariable(context, "y", null);
-    }
-
-    private void assertContextVariable(RuntimeContext context, String name, Object expected) {
-        assertEquals("value of " + name + " in context", expected, context.getVariable(name));
-    }
